'use strict';
let packet=null,currentCount=8,analysis=null,loading=false,navigation=0;
const $=id=>document.getElementById(id);
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function clear(id){$(id).replaceChildren();}
function date(value){if(!value)return 'Not established';const d=new Date(value);return d.toLocaleString('en-CA',{timeZone:'America/Toronto',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})+' · Toronto (UTC−04:00)';}
function cite(id,label){const b=node('button','source-button',label||'↗ '+id+' · inspect source');b.type='button';b.addEventListener('click',()=>showSource(id));return b;}
function showSource(id){const m=packet.messages.find(x=>x.id===id);if(!m)return;$('source-title').textContent=m.id+' · '+(packet.parties[m.party]||'Unverified sender');$('source-meta').textContent=date(m.sentAt)+' · '+m.shipment+' / '+m.version+' · Fictional verified identity';$('source-body').textContent=m.body;$('source-hash').textContent=m.sha256;document.querySelectorAll('.message').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));$('source-dialog').showModal();}
async function api(path,data){const res=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const result=await res.json();if(!res.ok)throw Error(result.error||'Request failed');return result;}
async function load(count){const ticket=++navigation;loading=true;$('load-status').textContent='Loading evidence…';try{const next=await api('/api/state?count='+count);if(ticket!==navigation)return false;packet=next;currentCount=count;analysis=null;render();$('load-status').textContent='Local evidence loaded';return true;}catch(e){if(ticket===navigation)$('load-status').textContent=e.message;return false;}finally{if(ticket===navigation)loading=false;}}
function render(){$('build-id').textContent=packet.buildId+' · BROWSER PREVIEW';const s=packet.state;clear('scenes');for(const scene of packet.scenes){const b=node('button','scene'+(scene.count===currentCount?' active':''),scene.label);b.dataset.scene=scene.id;b.addEventListener('click',()=>load(scene.count));$('scenes').append(b);}$('scene-caption').textContent=packet.scenes.find(x=>x.count===currentCount)?.caption||'Custom clarification scenario';$('risk-banner').className='risk-banner '+s.status.toLowerCase();$('risk-icon').textContent=s.status==='ALIGNED'?'✓':s.status==='CLARIFY'?'?':'!';$('risk-label').textContent=s.status==='ALIGNED'?'SHARED INSTRUCTION CONFIRMED':s.status==='CLARIFY'?'CLARIFICATION REQUIRED':'INSTRUCTION MISMATCH';$('risk-title').textContent=s.status==='ALIGNED'?'Everyone confirmed the same instruction.':s.status==='CLARIFY'?'Pause. One detail still needs a clear answer.':'The request changed. The driver’s instruction hasn’t.';$('risk-summary').textContent=s.status==='ALIGNED'?'Agreement recorded from three explicit source messages. This does not prove rerouting or delivery.':s.status==='CLARIFY'?'An incomplete, contradictory or revoked reference cannot become agreement.':'A new address and time are proposed. Received messages cannot replace explicit confirmation.';$('risk-count').textContent=s.risks.length;
const agreement=s.agreement,proposed=s.proposed;
for(const [prefix,value] of [['old',agreement],['new',proposed]]){$(prefix+'-address').textContent=value?.details.address||'No complete agreement';$(prefix+'-time').textContent=value?date(value.details.time):'Waiting for an exact, sourced instruction';}
$('agreement-version').textContent=agreement?.version||'—';$('proposed-version').textContent=proposed?.version||'—';const agreementEvidence=agreement?.parties.driver.evidence[0];$('agreement-source').textContent=agreementEvidence?'↗ '+agreementEvidence.messageId+' · historical acceptance':'No acceptance evidence';$('agreement-source').onclick=()=>agreementEvidence&&showSource(agreementEvidence.messageId);$('proposed-source').textContent=proposed?'↗ '+proposed.proposal.messageId+' · see request':'No valid proposal';$('proposed-source').onclick=()=>proposed&&showSource(proposed.proposal.messageId);$('change-strip').textContent=s.agreementValidity?.status==='revoked'?'Last complete agreement was later withdrawn. Historical acceptance is not current authorization.':s.agreementValidity?.status==='disputed'?'Original acceptance evidence is preserved; current responses dispute that agreement.':s.status==='ALIGNED'?'✓ Full address and time are aligned. No physical execution claim.':'Address + time must travel together. Historical agreement stays visible until the exact change is accepted.';
clear('parties');for(const [party,name] of Object.entries(packet.parties)){const response=proposed?.parties[party]||{status:'unconfirmed',evidence:[]};const card=node('article','party');card.append(node('div','avatar',name.split(' · ')[0].split(' ').map(x=>x[0]).join('')),node('div','role',party),node('h3','',name.split(' · ')[0]));card.append(node('span','status-tag '+response.status,(response.status==='received'?'RECEIVED ONLY':response.status.toUpperCase())+' · '+(s.activeVersion||'—')));for(const ev of response.evidence)card.append(cite(ev.messageId));const last=s.latestAcknowledgments[party];if(last&&last.version!==s.activeVersion){card.append(node('div','last','Still confirmed: '+last.version),cite(last.evidence[0].messageId,'↗ old instruction · '+last.evidence[0].messageId));}card.append(node('div','muted','Full address + time required'));$('parties').append(card);}
$('clarification').textContent=s.clarifications[0]||(s.status==='ALIGNED'?'No clarification is open. The exact version is explicitly accepted by all three parties.':(()=>{const party=Object.keys(packet.parties).find(p=>proposed?.parties[p].status!=='accepted');return 'Can '+(party||'each party')+' explicitly confirm '+s.activeVersion+': '+(proposed?.details.address||'the exact warehouse')+' at '+(proposed?.details.time||'the exact time with timezone')+'?';})());
clear('versions');for(const v of [...s.versions].reverse()){const row=node('div','version-row');row.append(node('b','',v.version));const detail=node('div','',v.details.address);detail.append(node('small','',date(v.details.time)));row.append(detail);const status=node('div');status.append(node('span','status-tag '+(v.revoked?'rejected':v.parties&&Object.values(v.parties).every(x=>x.status==='accepted')?'accepted':'neutral'),v.revoked?'WITHDRAWN':Object.values(v.parties).every(x=>x.status==='accepted')?'CONFIRMED':'PROPOSED'));status.append(document.createElement('br'),cite(v.proposal.messageId));if(v.withdrawal)status.append(document.createElement('br'),cite(v.withdrawal.messageId,'↗ withdrawal '+v.withdrawal.messageId));row.append(status);$('versions').append(row);}
clear('risks');$('signal-summary').textContent=s.risks.length+' evidence-linked signals';if(!s.risks.length)$('risks').append(node('p','muted','No open instruction mismatch in the evaluated synthetic messages.'));for(const risk of s.risks){const row=node('div','risk-row');row.append(node('div','risk-code',risk.code.replaceAll('_',' ')),node('div','',risk.text));for(const ev of risk.evidence)row.append(cite(ev.messageId,'↗ '+ev.messageId));$('risks').append(row);}
for(const warning of s.resolvedWarnings||[]){const row=node('div','risk-row');row.append(node('div','risk-code','RESOLVED HISTORY · '+warning.code.replaceAll('_',' ')),node('div','',warning.text),node('p','muted','Resolved by complete confirmation of '+warning.resolution.version+'. Original source preserved.'));for(const ev of warning.evidence)row.append(cite(ev.messageId,'↗ original '+ev.messageId));for(const ev of warning.resolution.evidence)row.append(cite(ev.messageId,'↗ resolution '+ev.messageId));$('risks').append(row);}
clear('messages');$('message-count').textContent=packet.messages.length;for(const m of [...packet.messages].reverse()){const card=node('article','message');card.dataset.id=m.id;card.id='message-'+m.id;const meta=node('div','message-meta');meta.append(node('span','',m.id+' · '+m.version),node('span','',new Date(m.sentAt).toLocaleTimeString('en-GB',{timeZone:'America/Toronto',hour:'2-digit',minute:'2-digit'})));const title=node('div','message-title');title.append(node('span','dot'),document.createTextNode((packet.parties[m.party]||'Unverified').split(' · ')[0]),node('span','message-type',m.kind.toUpperCase()));card.append(meta,title,node('p','',m.body),cite(m.id,'↗ Original message + hash'));$('messages').append(card);}
$('provider-detail').textContent='Prepared adapter: '+packet.provider.candidateModel+' via '+packet.provider.provider+'. Recorded synthetic runtime evidence is available when validated. Source text and model results are untrusted; advisory observations never update agreement.';clear('analysis-result');$('model-status').textContent=packet.recordedReview?'LEGACY NVIDIA REPLAY AVAILABLE':'NO VALIDATED RECORD';$('recorded-review').disabled=!packet.recordedReview;$('export').href='/api/export?count='+currentCount+'&review=none';}
$('close-source').addEventListener('click',()=>$('source-dialog').close());$('source-dialog').addEventListener('click',e=>{if(e.target===$('source-dialog'))$('source-dialog').close();});
$('next').addEventListener('click',()=>{if(loading)return;const next=packet.scenes.find(s=>s.count>currentCount)||packet.scenes[0];load(next.count);});
$('analyze').addEventListener('click',async()=>{const b=$('analyze');b.disabled=true;try{analysis=await api('/api/analyze',{mode:'mock',messages:packet.messages});$('model-status').textContent='SCRIPTED MOCK · NO MODEL CALL';clear('analysis-result');$('analysis-result').append(node('p','','Scripted mock classification only. No agreement state changed.'));for(const o of analysis.observations.slice(-4).reverse()){const row=node('div','observation',o.kind.toUpperCase()+' · '+o.version+' · ');row.append(cite(o.messageId));$('analysis-result').append(row);}}catch(e){$('analysis-result').textContent=e.message;}finally{b.disabled=false;}});
$('recorded-review').addEventListener('click',async()=>{if(!await load(8))return;analysis=packet.recordedReview;if(!analysis)return;$('export').href='/api/export?count=8&review=recorded';$('model-status').textContent='LEGACY NVIDIA RESPONSE · RECORDED REPLAY';clear('analysis-result');$('analysis-result').append(node('p','','Nebius Token Factory · '+analysis.model+' · recorded '+analysis.recordedOn+'. No new call. Advisory only; agreement unchanged.'));for(const o of analysis.observations){const row=node('div','observation',o.kind.toUpperCase()+' · '+o.version+' · ');row.append(cite(o.messageId),node('p','','Quoted: “'+o.quote+'”'),node('p','',o.explanation),node('small','muted','Model confidence '+o.confidence+' · uncalibrated'));$('analysis-result').append(row);}for(const q of analysis.questions)$('analysis-result').append(node('p','',q));});
$('ambiguity').addEventListener('click',async()=>{const ticket=++navigation;loading=true;try{const base=await api('/api/state?count=8');const proposal=base.messages.find(m=>m.id==='m05');proposal.details.time='Tomorrow at 3';proposal.body=proposal.body.replace('2026-10-27T11:30:00-04:00','Tomorrow at 3');const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(proposal.body));proposal.sha256=[...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('');const result=await api('/api/evaluate',{messages:base.messages});if(ticket!==navigation)return;packet={...base,state:result.state};currentCount=-1;analysis=null;render();$('load-status').textContent='Ambiguous-time scenario evaluated';}catch(e){if(ticket===navigation)$('load-status').textContent=e.message;}finally{if(ticket===navigation)loading=false;}});
$('export').addEventListener('click',e=>{if(!packet){e.preventDefault();return;}if(currentCount>=0&&(!analysis||analysis.recordedReplay))return;e.preventDefault();const value={format:'freightswitch-private-evidence-v1.3',buildId:packet.buildId,sourceDigest:packet.sourceDigest,visibleCount:currentCount,scenario:currentCount<0?'custom':packet.scenes.find(s=>s.count===currentCount)?.id||null,synthetic:true,realInference:analysis?.realInference===true,recordedReplay:analysis?.recordedReplay===true,state:packet.state,messages:packet.messages,advisory:analysis,notice:'Synthetic message agreement only. Recorded NVIDIA advisory, if included, is a replay; no new provider call, physical execution, sender authentication or carrier validation is claimed.'};const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download='FreightSwitch-'+packet.state.shipment+'-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);});
load(8);
